#include <stdio.h>

/* teste do desafio lista-de-convidados — counter_protocol (03-tdd 3.9.3).
   Quem DIGITA e o teste: fopen/fprintf escrevem os tres nomes num arquivo
   e o freopen troca o stdin por ele; a captura do stdout acontece dentro
   do proprio cenario (freopen + fflush, sem fclose no stdout). Dois
   cenarios com nomes diferentes: as linhas tem de vir da caixa lida,
   nunca de textos fixos no codigo. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void listaDeConvidados(void);

SM_TEST(a_lista_de_ana_bia_e_caio) {
    FILE *digitado = fopen("sm_entrada_1.tmp", "w");
    fprintf(digitado, "ana bia caio\n");
    fclose(digitado);
    freopen("sm_entrada_1.tmp", "r", stdin);

    freopen("sm_saida_1.tmp", "w", stdout);
    listaDeConvidados();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("o primeiro convidado", linha, "1. ana\n",
              "a linha 0 da caixa sai numerada como 1");
    fgets(linha, 80, f);
    checa_str("o segundo convidado", linha, "2. bia\n",
              "a linha 1 da caixa sai numerada como 2");
    fgets(linha, 80, f);
    checa_str("o terceiro convidado", linha, "3. caio\n",
              "a linha 2 da caixa sai numerada como 3");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a lista acaba no terceiro convidado: nenhuma linha extra e aceita");
    fclose(f);
}

