#include <stdio.h>

void listaDeConvidados(void) {
    char nomes[3][20] = {"", "", ""};
    for (int i = 0; i < 3; i++) {
        scanf("%19s", nomes[i]);
    }
    for (int i = 0; i < 3; i++) {
        printf("%d. %s\n", i + 1, nomes[i]);
    }
}
